#!/usr/bin/env bash
# Brings origin/main into one PR branch with a merge commit (never rewrites history), settling
# the conflicts that are purely mechanical, and verifies the result before pushing it.
#
#   scripts/sync-branch.sh <branch>            merge, verify, push
#   DRY_RUN=1 scripts/sync-branch.sh <branch>  merge and verify only, no push
#
# Exit 0: branch is up to date or was synced. Exit 1: needs a person (reason on stdout).
# Mechanical means: Cargo.lock (regenerated by cargo), and files marked `merge=union` in
# .gitattributes (append-only test files). Anything else that conflicts is left alone.
set -uo pipefail
branch="${1:?branch name}"

git fetch -q origin main "$branch" || { echo "cannot fetch $branch (deleted or merged?)"; exit 1; }
git checkout -q -B "sync/$branch" "origin/$branch"

if git merge-base --is-ancestor origin/main HEAD; then
  echo "up to date"
  exit 0
fi

if ! git merge --no-edit -m "Merge main into $branch" origin/main >/dev/null 2>&1; then
  conflicts="$(git diff --name-only --diff-filter=U)"
  other="$(printf '%s\n' "$conflicts" | grep -v '^Cargo.lock$' || true)"
  if [ -n "$other" ]; then
    git merge --abort
    printf 'conflicts in files that need a person:\n%s\n' "$other"
    exit 1
  fi
  # Only Cargo.lock: take main's and let cargo add this branch's dependencies back.
  git checkout --theirs Cargo.lock
  cargo metadata --format-version 1 >/dev/null 2>&1 || {
    git merge --abort
    echo "cargo could not regenerate Cargo.lock"
    exit 1
  }
  git add Cargo.lock
  git commit -q --no-edit
fi

# The merged result must pass the same checks CI runs before it is pushed.
cargo fmt --all
if ! git diff --quiet; then
  git commit -qam "Format after merging main"
fi
if ! out="$(cargo clippy --workspace --all-targets 2>&1 && cargo test --workspace 2>&1)"; then
  printf 'the merged result fails checks:\n%s\n' "$(printf '%s\n' "$out" | tail -30)"
  exit 1
fi

if [ -n "${DRY_RUN:-}" ]; then
  echo "dry run: merge is clean and passes; not pushing"
  exit 0
fi
git push -q origin "HEAD:$branch"
echo "synced"
